 for(const change of [b=>delete b.notepads,b=>delete b.actionTables,b=>b.actionTables.rows[0].parameter="id",b=>b.actionTables.rows[0].field="note"]){const b=structuredClone(mapped);change(b);assert.equal(compileWorkshopModule(source,"page",b,destination).draft,undefined);}assert.equal(compileWorkshopModule(source,"page",mapped,{...destination,profile:"platform.page.v2.80"}).draft,undefined);
