test("default Leaderboard uses an independent host Top-N plan and original sole active producer",()=>{const m=sourceModule();m.widgets.rank={id:"rank",name:"Top exposure",type:"Leaderboard",config:{objectSetVarId:"notes",property:"revenueImpact",limit:8,activeVarId:"selected"}};m.sections.root.children[0]={kind:"widget",id:"rank"};const mapped={...bindings,fields:{Asset:{...bindings.fields.Asset,revenueImpact:"qty"}},leaderboards:{rank:{labelField:"note"}}},typed={...target,entities:[{...target.entities[0],fields:[...target.entities[0].fields,{name:"qty",type:"decimal"}]}]},source=JSON.stringify(m),r=compileWorkshopModule(source,"page",mapped,typed);assert.ok(r.draft,JSON.stringify(r.diagnostics));const rank=r.draft.sections.find(s=>s.widget==="record-leaderboard"),q=r.draft.document.queries[r.draft.document.variables[rank.collectionVariable].source.query],detail=r.draft.sections.find(s=>s.widget==="detail");assert.deepEqual(rank.leaderboard,{valueField:"qty",labelField:"note",limit:8,ascending:false});assert.deepEqual(q.sort,["-qty","id"]);assert.equal(q.limit,8);assert.equal(q.offset,0);assert.equal(r.draft.document.variables[detail.recordVariable].source.section,rank.id);assert.equal(r.source,source);assert.equal(compileWorkshopModule(source,"page",bindings,typed).draft,undefined);assert.equal(compileWorkshopModule(source,"page",mapped,{...typed,profile:"platform.page.v2.50"}).draft,undefined);m.widgets.rank.config.ascending=true;const asc=compileWorkshopModule(JSON.stringify(m),"page",mapped,typed);assert.ok(asc.draft);assert.deepEqual(Object.values(asc.draft.document.queries).find(q=>q.sort?.[0]==="qty").sort,["qty","id"]);m.sections.root.children.push({kind:"widget",id:"table"});assert.equal(compileWorkshopModule(JSON.stringify(m),"page",mapped,typed).draft,undefined);});
