test("default Gauge maps original average field and freezes numeric precision, display maximum, suffix and threshold",()=>{const m=sourceModule();m.variables.push({id:"avgAvailability",name:"Average availability",type:"numeric",definitionKind:"objectSetAggregation",inputVarId:"notes",transformations:[{op:"aggregate",args:{by:"avgAvailability"}}]});m.widgets.gauge={id:"gauge",name:"Fleet gauge",type:"Gauge",config:{variableId:"avgAvailability",label:"Fleet availability",max:100,suffix:"%",warnAt:60}};m.sections.root.children.push({kind:"widget",id:"gauge"});const mapped={...bindings,aggregates:{avgAvailability:{measure:"avg:availability"}}},typed={...target,entities:[{...target.entities[0],fields:[...target.entities[0].fields,{name:"availability",type:"decimal"}]}]},source=JSON.stringify(m),r=compileWorkshopModule(source,"page",mapped,typed);assert.ok(r.draft,JSON.stringify(r.diagnostics));const gauge=r.draft.sections.find(s=>s.widget==="gauge"),v=r.draft.document.variables[gauge.gaugeValueVariable];assert.equal(v.type,"number");assert.equal(v.mode,"aggregate");assert.equal(v.source.measure,"avg:availability");assert.deepEqual(gauge.gauge,{max:100,warnAt:60,label:"Fleet availability",suffix:"%"});assert.equal(r.source,source);assert.equal(compileWorkshopModule(source,"page",bindings,typed).draft,undefined);assert.equal(compileWorkshopModule(source,"page",mapped,{...typed,profile:"platform.page.v2.48"}).draft,undefined);for(const change of [c=>c.max=0,c=>c.warnAt="60",c=>c.script="predict()"]){const copy=structuredClone(m);change(copy.widgets.gauge.config);assert.equal(compileWorkshopModule(JSON.stringify(copy),"page",mapped,typed).draft,undefined);}const fn=structuredClone(m);fn.variables.find(v=>v.id==="avgAvailability").definitionKind="function";assert.equal(compileWorkshopModule(JSON.stringify(fn),"page",mapped,typed).draft,undefined);});
